function generate_digest(reg_type, value):
    if reg_type == REG_INT:
        trailing = count_trailing_zeros(value) & 0x3F
        leading = count_leading_zeros(value) & 0x3F
        lsb6 = value & 0x3F
        return trailing ^ (leading << 3) ^ (lsb6 << 6)
    elif reg_type == REG_FLAGS:
        f = value & 0xF
        return (f << 8) | (f << 4) | f
    elif reg_type == REG_FP:
        return ((value >> 55) & 0x1FF) << 3
    return 0

function on_decode(inst):
    for dest_reg in inst.dest_registers:
        reg_table[dest_reg].valid = 0
        reg_table[dest_reg].payload = inst.rob_tag // 14-bit ROB index
        reg_table[dest_reg].decay_ctr = 255

function on_instruction_decoded_tick():
    // Decrement aging counter every instruction decoded
    for r = 0 to 64:
        if reg_table[r].valid == 1:
            if reg_table[r].decay_ctr > 0:
                reg_table[r].decay_ctr -= 1
            if reg_table[r].decay_ctr == 0:
                reg_table[r].valid = 0 // Invalidate stale digest

function on_execution_complete(rob_tag, dest_reg, value, reg_type):
    if reg_table[dest_reg].valid == 0 and reg_table[dest_reg].payload == rob_tag:
        reg_table[dest_reg].payload = generate_digest(reg_type, value)
        reg_table[dest_reg].valid = 1
        reg_table[dest_reg].decay_ctr = 255

function on_pipeline_squash(recover_rob_tag):
    // On mispredict recovery, in-flight instruction tags are flushed
    // Completed registers retain valid digests, enabling recovery-path correlation
    for r = 0 to 64:
        if reg_table[r].valid == 0:
            if is_younger_than_or_equal(reg_table[r].payload, recover_rob_tag):
                // Revert to invalid or architectural state
                reg_table[r].valid = 0

function predict_sR(PC):
    sR_sum = 0
    for b = 0 to 7:
        regs_in_bank = get_registers_for_bank(b)
        // Compute usefulness vector from UT0, UT1, UT2
        idx0 = Hash_UT0(PC) % 8
        idx1 = Hash_UT1(PC) % 8
        idx2 = Hash_UT2(PC) % 8

        max_u = -infinity
        best_reg = null
        for r in regs_in_bank:
            u_val = UT[b][0][idx0][r] + UT[b][1][idx1][r] + UT[b][2][idx2][r]
            if reg_table[r].valid == 1:
                if u_val > max_u:
                    max_u = u_val
                    best_reg = r

        if best_reg != null and max_u > 0:
            digest = reg_table[best_reg].payload[11:0]
            // Query WT0, WT1, WT2
            w0 = WT[b][0][Hash_WT0(PC, digest) % 512]
            w1 = WT[b][1][Hash_WT1(PC, digest) % 256]
            w2 = WT[b][2][Hash_WT2(PC, digest) % 128]
            bank_sum = w0 + w1 + w2
            // Scale bank output by 2.5 per Figure 5(c)
            sR_sum += int(bank_sum * 2.5)
        else:
            // Multiplier x0 if no valid register or non-positive usefulness
            sR_sum += 0

    return sR_sum
